import{_ as l,a8 as o,o as i,c as g,ah as u,a as n,a3 as s,K as a,L as p}from"./chunks/framework.B6ehkn__.js";import"./chunks/theme.BfMjDZ3-.js";const x=JSON.parse('{"title":"网页笔记工作流","description":"","frontmatter":{"title":"网页笔记工作流","tags":["published"],"date_published":"2026-08-04T00:00:00.000Z","status":"published"},"headers":[],"relativePath":"vault/作坊/网页笔记工作流-从5个Agent到3个.md","filePath":"vault/Workshop/网页笔记工作流-从5个Agent到3个.md","lastUpdated":1793173648000}'),c={name:"vault/作坊/网页笔记工作流-从5个Agent到3个.md"};function h(b,t,q,A,k,m){const e=o("VPNolebaseInlineLinkPreview"),r=o("NolebaseGitContributors"),d=o("NolebaseGitChangelog");return i(),g("div",null,[t[6]||(t[6]=u(`<h1 id="五个-agent-太浪费了-我为什么把-ai-工作流从-5-个-agent-减到-3-个" tabindex="-1">五个 Agent 太浪费了：我为什么把 AI 工作流从 5 个 Agent 减到 3 个 <a class="header-anchor" href="#五个-agent-太浪费了-我为什么把-ai-工作流从-5-个-agent-减到-3-个" aria-label="Permalink to “五个 Agent 太浪费了：我为什么把 AI 工作流从 5 个 Agent 减到 3 个”">​</a></h1><blockquote><p>摘要：很多人设计 AI 工作流时有个本能反应——&quot;多拆几个 Agent，各管一段，肯定更可靠&quot;。但我在实践中发现，<strong>不是每一步都需要独立的 AI 上下文</strong>。URL 分类、文本提取、汇总提案这些事，让 AI 做反而引入幻觉，让调度器（主会话）自己做更准更快。本文分享一个「网页笔记工作流」从 5 个独立 Agent 精简到&quot;调度器（主会话） + 3 个 subagent&quot;的思考过程，以及为什么真正的安全闸门只有一个——核查官必须独立，其他都可以商量。</p></blockquote><hr><h2 id="一、问题的起点" tabindex="-1">一、问题的起点 <a class="header-anchor" href="#一、问题的起点" aria-label="Permalink to “一、问题的起点”">​</a></h2><p>这套工作流的初衷很简单：把收藏的网页交给 AI 提炼笔记，但不想被它一本正经地编造糊弄。</p><p>初版设计是<strong>五个独立 Agent</strong>，各管一段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>Agent 0 采编 → Agent 1 归类师 → Agent 2 笔记匠 → Agent 3 核查官 → Agent 4 确认员</span></span></code></pre></div><p>看起来分工明确，每个 Agent 都是独立的 AI 上下文，互不可见，互不影响。但实际跑起来我发现一个问题：<strong>很多步骤并不需要 AI。</strong></p><p>不是&quot;用 AI 能不能做&quot;的问题——当然能——而是&quot;用 AI 做是不是更好&quot;。URL 分类是正则匹配，文本提取是调 CLI 工具，汇总提案是格式整理。这些事用 AI 做，不但慢、贵，还会引入额外的幻觉风险——AI 可能猜错媒体格式，可能脑补提取失败的原因，可能在汇总时自作主张。</p><p>于是我开始思考：<strong>哪些步骤真正需要独立的 AI 判断？哪些让调度器（主会话）自己做更靠谱？</strong></p><hr><h2 id="二、关键决策-不是每步都需要-agent" tabindex="-1">二、关键决策：不是每步都需要 Agent <a class="header-anchor" href="#二、关键决策-不是每步都需要-agent" aria-label="Permalink to “二、关键决策：不是每步都需要 Agent”">​</a></h2><p>逐步骤分析：</p><p><strong>采编（原 Agent 0）→ 主会话内化。</strong></p><p>它的工作本质是：看 URL 的域名和路径判断是视频还是图文 → 调用对应的工具提取文本。URL 分类用正则，文本提取是执行 <code>python tools/extract-document.py</code> 或 <code>python tools/extract-webpage.py</code>。这完全是<strong>确定性逻辑</strong>——输入相同，输出一定相同。让 AI 做反而可能猜错（比如把 <code>music.youtube.com</code> 误判为视频而不是音频）。所以这一步交给调度器（主会话）自己，不创建 subagent。</p><p><strong>归类师（原 Agent 1）→ 保留独立。</strong></p><p>四选一分类（学习/借鉴/内容补充/可归档）需要理解正文语义，这是 AI 真正擅长的。同时，归类师的判断不应影响笔记匠——如果归类师给了&quot;学习&quot;标签，笔记匠可能&quot;为了证明值得学习而过度提炼&quot;。独立上下文隔离了这种认知污染。</p><p><strong>笔记匠（原 Agent 2）→ 保留独立。</strong></p><p>笔记提炼是核心创作任务，需要完整的上下文专注正文。独立意味着它只关注&quot;从正文中提取什么&quot;，不受其他任务干扰。</p><p><strong>核查官（原 Agent 3）→ 必须独立，不可妥协。</strong></p><p>这是整套系统的<strong>核心安全机制</strong>。文档里写得很清楚：</p><blockquote><p>&quot;AI 提炼东西的时候会一脸自信地编……写笔记的 Agent 不能来核查自己。&quot;</p></blockquote><p>如果核查和笔记匠是同一个 Agent，它天然会为自己的笔记辩护——&quot;翻倍&quot;那句它自己写的，它不会觉得有问题。<strong>这条必须守死。</strong></p><p><strong>确认员（原 Agent 4）→ 主会话内化。</strong></p><p>确认员的工作是：读前几道产出、汇总成&quot;待确认提案&quot;、全部停在待确认。它不读原文、不做新判断，只是<strong>格式整理 + 行为约束</strong>。调度器（主会话）自己就能做，不需要独立的 AI。</p><p><strong>最终架构：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>调度器（主会话）</span></span>
<span class="line"><span>├── 1. 采编（主会话自己做——URL 正则 + CLI 工具提取文本）</span></span>
<span class="line"><span>│      → 产出 00-采编清单.md</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 2. 归类师（独立 subagent——四选一语义分类）</span></span>
<span class="line"><span>│      → 产出 01-整理清单.md</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 3. 笔记匠（独立 subagent——提取 3~5 条核心要点）</span></span>
<span class="line"><span>│      → 产出 02-笔记.md</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 4. 核查官（全新 subagent——逐条比对原文 vs 笔记）</span></span>
<span class="line"><span>│      → 产出 03-核查表.md</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── 5. 确认（主会话自己做——汇总提案，全部停在待确认）</span></span>
<span class="line"><span>       → 产出 04-待确认提案.md</span></span></code></pre></div><p><strong>对比一下：</strong></p><table tabindex="0"><thead><tr><th>步骤</th><th>原来</th><th>现在</th><th>理由</th></tr></thead><tbody><tr><td>采编</td><td>独立 AI Agent</td><td><strong>主会话内化</strong></td><td>正则 + CLI 是确定性逻辑</td></tr><tr><td>归类师</td><td>独立 AI Agent</td><td><strong>独立 subagent</strong></td><td>语义分类需要 AI</td></tr><tr><td>笔记匠</td><td>独立 AI Agent</td><td><strong>独立 subagent</strong></td><td>核心提炼任务</td></tr><tr><td>核查官</td><td>独立 AI Agent</td><td><strong>独立 subagent（必须全新）</strong></td><td>安全闸门</td></tr><tr><td>确认员</td><td>独立 AI Agent</td><td><strong>主会话内化</strong></td><td>格式整理 + 约束</td></tr></tbody></table><p>LLM 调用次数从 5 次减到 3 次，节省 40%，而且<strong>消除幻觉风险最大的两个环节</strong>——采编和确认不再依赖 AI 猜测。</p><hr><h2 id="三、采编阶段具体做什么" tabindex="-1">三、采编阶段具体做什么 <a class="header-anchor" href="#三、采编阶段具体做什么" aria-label="Permalink to “三、采编阶段具体做什么”">​</a></h2><p>既然采编交给了调度器（主会话），它具体怎么做？</p><p><strong>媒体格式判断</strong>（优先级从高到低）：</p><ol><li>URL 路径末尾扩展名（忽略查询参数），<code>.pdf</code>/<code>.docx</code> → 文档</li><li>域名匹配：<code>music.163.com</code> → 音频；<code>youtube.com/watch</code> → 视频；<code>mp.weixin.qq.com</code> → 图文</li><li>URL 路径含 <code>/article/</code>、<code>/blog/</code>、<code>/posts/</code> → 图文</li><li>以上都不满足 → 无法判断</li></ol><p><strong>文本提取</strong>调用统一的 CLI 工具：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span># 文档提取</span></span>
<span class="line"><span>python tools/extract-document.py paper.pdf</span></span>
<span class="line"><span># → {&quot;success&quot;: true, &quot;text&quot;: &quot;...&quot;, &quot;char_count&quot;: 144, &quot;method&quot;: &quot;pypdf&quot;}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 图文页面提取（通过 BrowserSkill 操作已登录的浏览器）</span></span>
<span class="line"><span>python tools/extract-webpage.py https://example.com/article</span></span>
<span class="line"><span># → {&quot;success&quot;: true, &quot;text&quot;: &quot;...&quot;, &quot;char_count&quot;: 125, &quot;method&quot;: &quot;bsk-webpage&quot;}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 视频页面提取</span></span>
<span class="line"><span>python tools/extract-video-text.py https://www.bilibili.com/video/BV1xx</span></span>
<span class="line"><span># → {&quot;success&quot;: true, &quot;text&quot;: &quot;...&quot;, &quot;char_count&quot;: 1613, &quot;method&quot;: &quot;bsk-video&quot;}</span></span></code></pre></div><p>所有工具输出统一 JSON 格式，调度器（主会话）直接解析即可。提取失败时如实标记&quot;无法提取&quot;，不硬凑。</p><hr><h2 id="四、实测效果" tabindex="-1">四、实测效果 <a class="header-anchor" href="#四、实测效果" aria-label="Permalink to “四、实测效果”">​</a></h2><p>我在 7 条混合内容上测试了完整的采编能力：</p><table tabindex="0"><thead><tr><th>内容</th><th>媒体格式</th><th>提取方式</th><th>结果</th></tr></thead><tbody><tr><td>微信公众号文章</td><td>图文</td><td>已有正文（567 chars）</td><td>✅</td></tr><tr><td>CSDN 博客</td><td>图文</td><td>已有正文（819 chars）</td><td>✅</td></tr><tr><td>YouTube 视频</td><td>视频</td><td>BrowserSkill 读取页面文本</td><td>✅（实际 B站视频 1613 chars）</td></tr><tr><td>B站视频</td><td>视频</td><td>BrowserSkill 读取页面文本</td><td>✅</td></tr><tr><td>PDF 论文</td><td>文档</td><td>pypdf 提取（144 chars）</td><td>✅</td></tr><tr><td>DOCX 方案</td><td>文档</td><td>python-docx 提取（114 chars）</td><td>✅</td></tr><tr><td>普通网页</td><td>无法判断</td><td>BrowserSkill 读取</td><td>✅</td></tr></tbody></table><p>媒体格式分类 7/7 正确，文档提取 2/2 成功。视频和无法判断的页面通过 BrowserSkill 读取了可见文本（标题、描述、评论等）。</p><hr><h2 id="五、关键设计约束" tabindex="-1">五、关键设计约束 <a class="header-anchor" href="#五、关键设计约束" aria-label="Permalink to “五、关键设计约束”">​</a></h2><p><strong>关于&quot;不抓网页&quot;：</strong></p><p>这套工作流本身不发起 HTTP 请求去抓网页。通过 BrowserSkill 操作的是<strong>用户已登录的浏览器</strong>，所以能访问付费墙后的内容和需要登录的页面。这是工具链设计上的一个重要选择——不越俎代庖，只利用用户已有的浏览器会话。</p><p><strong>关于&quot;只读不改&quot;：</strong></p><p>原文文件全程只读，不复制、不移动、不修改。每次运行只记录原文路径，核查时按路径回到原文比对。多次运行互不覆盖。</p><p><strong>关于&quot;全部停在待确认&quot;：</strong></p><p>任何删除、归档、发布、写入长期记录的动作都停在&quot;待确认&quot;，用户逐条点头后才落地。AI 可以无限地&quot;想&quot;和&quot;建议&quot;，但凡要&quot;落地动手&quot;，都停在用户那道闸前。</p><hr><h2 id="六、三种使用方式" tabindex="-1">六、三种使用方式 <a class="header-anchor" href="#六、三种使用方式" aria-label="Permalink to “六、三种使用方式”">​</a></h2><ol><li><p><strong>多 Agent 版（推荐）</strong>：工具支持 subagent 时，调度器（主会话）自动创建 3 个 subagent（归类师、笔记匠、核查官），采编和确认由调度器（主会话）自己执行。</p></li><li><p><strong>单对话框版（零门槛）</strong>：分三段交付。第一段调度器（主会话）做采编 + 归类 + 提炼后停下；第二段新开对话做核查（这一步不能省，否则又变成自己查自己）；第三段调度器（主会话）汇总确认。</p></li><li><p><strong>文件流水线</strong>：五个文件并列写入 <code>runs/&lt;日期-主题&gt;/</code> 目录，调度器（主会话） + 3 个 subagent 接力。</p></li></ol><hr><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>回到最开始的问题：<strong>不是每一步都需要独立的 AI 上下文。</strong></p><p>真正需要独立 AI 判断的只有三步——归类师理解语义、笔记匠专注提炼、核查官独立比对。采编和确认是确定性逻辑，让调度器（主会话）自己做更准、更快、零幻觉风险。</p><p>这不是在偷懒少建几个 Agent，而是在认真思考：<strong>哪些事只有 AI 能做，哪些事 AI 做反而更差。</strong></p>`,59)),n("p",null,[t[1]||(t[1]=s("项目已开源：",-1)),a(e,{href:"https://github.com/star-nebula/WebNote-Workflow",target:"_blank",rel:"noreferrer"},{default:p(()=>[...t[0]||(t[0]=[s("github.com/star-nebula/WebNote-Workflow",-1)])]),_:1}),t[2]||(t[2]=s("。仓库含完整文档、提示词和工具代码，欢迎 Star / Fork。",-1))]),t[7]||(t[7]=n("hr",null,null,-1)),n("p",null,[n("em",null,[t[4]||(t[4]=s("设计参考：",-1)),a(e,{href:"https://www.axtonliu.ai/newsletters/ai-2/posts/agent-os-workstation-division",target:"_blank",rel:"noreferrer"},{default:p(()=>[...t[3]||(t[3]=[s("Agent OS 的第一课：会分工，才会用 Agent",-1)])]),_:1}),t[5]||(t[5]=s("（Axton Liu）。",-1))])]),a(r),a(d)])}const _=l(c,[["render",h]]);export{x as __pageData,_ as default};
